"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Instagram,
  Twitter,
  Youtube,
  Gift,
  CheckCircle2,
  Trophy,
  CreditCard,
  Clock,
  X,
  Loader2,
  Send,
  ExternalLink,
  ChevronRight,
  Facebook,
  Sparkles,
} from "lucide-react";
import { cn } from "@/lib/utils";

// --- Types ---
type ClaimStatus = "idle" | "pending" | "approved";

interface SocialTask {
  id: string;
  platform: string;
  profileUrl: string;
  icon: React.ElementType;
  rewardAmount: number;
  status: ClaimStatus;
  actionLabel: string;
  placeholder: string;
  cardStyle: string; // The specific brand colors
}

// --- Config ---
const SOCIAL_TASKS: SocialTask[] = [
  {
    id: "soc-1",
    platform: "Instagram",
    profileUrl: "https://instagram.com",
    icon: Instagram,
    rewardAmount: 50,
    status: "idle",
    actionLabel: "Follow & Tag",
    placeholder: "Your Instagram Handle",
    cardStyle: "bg-gradient-to-bl from-[#833ab4] via-[#fd1d1d] to-[#fcb045]",
  },
  {
    id: "soc-2",
    platform: "X / Twitter",
    profileUrl: "https://twitter.com",
    icon: Twitter,
    rewardAmount: 50,
    status: "idle",
    actionLabel: "Follow us",
    placeholder: "Your X Handle",
    cardStyle: "bg-gradient-to-tr from-blue-600 to-black",
  },
  {
    id: "soc-3",
    platform: "YouTube",
    profileUrl: "https://youtube.com",
    icon: Youtube,
    rewardAmount: 100,
    status: "idle",
    actionLabel: "Subscribe",
    placeholder: "Your Channel Name",
    cardStyle: "bg-gradient-to-tr from-red-600 to-red-900",
  },
  {
    id: "soc-4",
    platform: "Facebook",
    profileUrl: "https://facebook.com",
    icon: Facebook,
    rewardAmount: 50,
    status: "idle",
    actionLabel: "Like Page",
    placeholder: "Your Facebook Name",
    cardStyle: "bg-gradient-to-br from-[#1877F2] to-[#0F5BD8]",
  },
];

export default function RewardsPage() {
  const [socials, setSocials] = useState(SOCIAL_TASKS);
  const [selectedTask, setSelectedTask] = useState<SocialTask | null>(null);
  const [usernameInput, setUsernameInput] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmitClaim = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    await new Promise((resolve) => setTimeout(resolve, 1500));
    setSocials((prev) =>
      prev.map((t) => (t.id === selectedTask?.id ? { ...t, status: "pending" } : t))
    );
    setIsSubmitting(false);
    setSelectedTask(null);
  };

  return (
    <div className="min-h-screen bg-black text-white selection:bg-white selection:text-black">
      <main className="max-w-6xl mx-auto px-6 py-20 pb-32 space-y-24">
        
        {/* --- 1. MONOCHROME HERO SECTION --- */}
        <section className="flex flex-col lg:flex-row items-center justify-between gap-12 pt-10">
          <div className="max-w-xl space-y-6 text-center lg:text-left">
            <h1 className="text-6xl md:text-8xl font-black tracking-tighter leading-[0.85]">
              MEMBERS <br /> <span className="text-zinc-500 italic">CLUB.</span>
            </h1>
            <p className="text-zinc-500 text-lg font-medium max-w-sm mx-auto lg:mx-0">
              Your social influence is currency. Connect, claim, and spend your credits instantly.
            </p>
          </div>

          {/* Black Chrome Wallet Card */}
          <div className="relative w-full max-w-md aspect-[1.58/1] bg-zinc-900 rounded-[2.5rem] p-8 border border-white/10 shadow-[0_0_50px_rgba(255,255,255,0.05)] overflow-hidden flex flex-col justify-between group">
            <div className="absolute inset-0 bg-gradient-to-br from-white/5 to-transparent pointer-events-none" />
            
            <div className="relative z-10 flex justify-between items-start">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-white flex items-center justify-center text-black shadow-[0_0_20px_white]">
                  <Sparkles size={20} />
                </div>
                <span className="font-bold text-xs tracking-[0.3em] opacity-80 uppercase">Black Tier</span>
              </div>
              <CreditCard className="opacity-30" size={28} />
            </div>

            <div className="relative z-10">
              <p className="text-zinc-500 text-[10px] font-black uppercase tracking-widest mb-1">Total Credits</p>
              <h2 className="text-6xl font-black tracking-tighter">₹1,250</h2>
            </div>

            <div className="relative z-10 flex justify-between items-end border-t border-white/5 pt-4">
              <div>
                <p className="text-[9px] text-zinc-500 font-bold uppercase tracking-widest">Card Holder</p>
                <p className="font-bold text-sm">AJMAL</p>
              </div>
              <p className="font-mono text-xs opacity-30 tracking-widest">**** 8829</p>
            </div>
          </div>
        </section>

        {/* --- 2. RELATABLE SOCIAL CARDS --- */}
        <section className="space-y-8">
          <div className="flex items-center gap-4 px-2">
             <div className="h-px flex-1 bg-zinc-900" />
             <h2 className="text-sm font-black uppercase tracking-[0.4em] text-zinc-500">Social Gift Cards</h2>
             <div className="h-px flex-1 bg-zinc-900" />
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-8">
            {socials.map((task) => (
              <SocialGiftCard 
                key={task.id} 
                task={task} 
                onOpen={() => task.status === "idle" && setSelectedTask(task)} 
              />
            ))}
          </div>
        </section>

        {/* --- 3. MONO MILESTONE SECTION --- */}
        <section className="border border-zinc-900 rounded-[3rem] p-10 flex flex-col md:flex-row items-center gap-10">
          <div className="w-20 h-20 rounded-2xl bg-white text-black flex items-center justify-center shrink-0 shadow-[0_0_30px_rgba(255,255,255,0.2)]">
            <Trophy size={32} />
          </div>
          <div className="flex-1 space-y-4 w-full text-center md:text-left">
            <div className="flex justify-between items-end">
              <h3 className="text-2xl font-black italic uppercase">Silver Member</h3>
              <p className="text-xs font-bold text-zinc-500 tracking-widest">65% TO GOLD</p>
            </div>
            <div className="w-full h-3 bg-zinc-950 rounded-full overflow-hidden p-0.5 border border-zinc-900">
               <motion.div 
                initial={{ width: 0 }} 
                whileInView={{ width: "65%" }}
                className="h-full bg-white rounded-full shadow-[0_0_15px_white]" 
               />
            </div>
          </div>
          <ChevronRight className="text-zinc-800 hidden md:block" />
        </section>
      </main>

      {/* --- CLAIM MODAL --- */}
      <AnimatePresence>
        {selectedTask && (
          <ClaimModal 
            task={selectedTask} 
            input={usernameInput} 
            setInput={setUsernameInput} 
            isSubmitting={isSubmitting} 
            onClose={() => setSelectedTask(null)} 
            onSubmit={handleSubmitClaim} 
          />
        )}
      </AnimatePresence>
    </div>
  );
}

// --- Card Component (Keeping original colors) ---
function SocialGiftCard({ task, onOpen }: { task: SocialTask; onOpen: () => void }) {
  const Icon = task.icon;
  const isPending = task.status === "pending";
  const isApproved = task.status === "approved";

  return (
    <motion.div
      whileHover={{ y: -8, scale: 1.01 }}
      onClick={onOpen}
      className={cn(
        "relative aspect-[1.58/1] rounded-[2.5rem] p-8 flex flex-col justify-between overflow-hidden cursor-pointer shadow-2xl transition-all duration-500",
        task.cardStyle,
        (isApproved || isPending) && "grayscale opacity-60 cursor-default"
      )}
    >
      {/* Texture */}
      <div className="absolute inset-0 bg-white/5 opacity-20 pointer-events-none" />

      <div className="relative z-10 flex justify-between items-start">
        <div className="p-3 bg-black/20 backdrop-blur-xl rounded-2xl border border-white/10">
          <Icon size={28} className="text-white" />
        </div>
        <div className="text-right">
          <p className="text-4xl font-black tracking-tighter text-white">₹{task.rewardAmount}</p>
          <p className="text-[10px] font-bold uppercase tracking-widest text-white/60 leading-none">Gift Credit</p>
        </div>
      </div>

      <div className="relative z-10">
        <p className="text-[10px] font-black uppercase tracking-widest text-white/50 mb-1">Action Required</p>
        <h4 className="text-2xl font-bold tracking-tight text-white">{task.actionLabel}</h4>
      </div>

      <div className="relative z-10 flex justify-between items-center">
        {task.status === "idle" ? (
          <div className="flex items-center gap-2 text-xs font-black uppercase tracking-widest bg-white text-black px-5 py-2.5 rounded-full">
            Claim Now <ChevronRight size={14} />
          </div>
        ) : (
          <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest bg-black/40 text-white px-5 py-2.5 rounded-full backdrop-blur-md">
            {isPending ? <><Clock size={12} /> Verification Pending</> : <><CheckCircle2 size={12} /> Claimed</>}
          </div>
        )}
        <div className="w-10 h-10 rounded-full border border-white/20 flex items-center justify-center text-white/50">
          <ExternalLink size={14} />
        </div>
      </div>
    </motion.div>
  );
}

// --- Modal Component ---
function ClaimModal({ task, input, setInput, isSubmitting, onClose, onSubmit }: any) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-6">
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 bg-black/90 backdrop-blur-md" onClick={onClose} />
      <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }} className="relative w-full max-w-sm bg-zinc-900 border border-zinc-800 rounded-[2.5rem] p-10">
        <button onClick={onClose} className="absolute top-6 right-6 text-zinc-500 hover:text-white"><X size={24} /></button>
        <div className="text-center space-y-4 mb-8">
          <div className={cn("w-16 h-16 rounded-2xl mx-auto flex items-center justify-center text-white", task.cardStyle)}>
             <task.icon size={32} />
          </div>
          <h3 className="text-2xl font-black italic uppercase tracking-tight">Verify Profile</h3>
          <p className="text-zinc-500 text-sm">Submit your handle for verification.</p>
        </div>
        <form onSubmit={onSubmit} className="space-y-4">
          <input 
            type="text" 
            placeholder={task.placeholder} 
            value={input} 
            onChange={(e) => setInput(e.target.value)}
            className="w-full bg-black border border-zinc-800 rounded-2xl px-6 py-4 outline-none focus:border-white transition-colors text-white font-bold"
          />
          <button disabled={isSubmitting || !input} className="w-full py-5 bg-white disabled:bg-zinc-800 text-black font-black rounded-2xl uppercase tracking-tighter transition-all flex items-center justify-center gap-2">
            {isSubmitting ? <Loader2 className="animate-spin" /> : "Submit Request"}
          </button>
        </form>
      </motion.div>
    </div>
  );
}